const item = $input.first().json;

const payload = item.body || item;

const conv = payload.data?.conversation || {};
const ctx = payload.data?.context || {};

const userMessage = conv.message || '';
const history = ctx.history || [];
const bookingInfo = ctx.booking || null;

const systemPrompt = 'Eres el asistente virtual de LocalPlug, un servicio de conserjería premium para viajeros. Tu trabajo es: 1) Ayudar con reservas, paquetes y servicios 2) Responder preguntas sobre la ciudad, aeropuerto, transporte 3) Guiar al usuario en el proceso de reserva. Reglas: Responde en el MISMO idioma del usuario. Sé breve, amable y profesional. Usa emojis con moderación. Si el usuario pide hablar con un humano, confirma que un agente lo contactará.';

const messages = [{ role: 'system', content: systemPrompt }];

if (bookingInfo) {
  messages.push({ role: 'system', content: 'Booking info: ' + JSON.stringify(bookingInfo) });
}

for (const m of history.slice(-6)) {
  messages.push({ role: m.role || 'user', content: m.content });
}

messages.push({ role: 'user', content: userMessage });

const escalationKeywords = [
  'hablar con alguien', 'hablar con una persona', 'hablar con un agente', 'hablar con un humano',
  'talk to someone', 'talk to a person', 'talk to an agent', 'talk to a human',
  'queja', 'problema', 'reclamo'
];

const isEscalation = escalationKeywords.some(k => userMessage.toLowerCase().includes(k));

const openaiPayload = {
  model: 'meta/llama-3.1-8b-instruct',
  messages: messages,
  temperature: 0.7,
  max_tokens: 500
};

return [{
  json: {
    requestBody: JSON.stringify(openaiPayload),
    _isEscalation: isEscalation
  }
}];

const item = $input.first().json;

let aiReply = '';

if (item.choices && Array.isArray(item.choices) && item.choices.length > 0) {
  aiReply = item.choices[0].message?.content || '';
} else if (item.message?.content) {
  aiReply = item.message.content;
} else if (item.response) {
  aiReply = item.response;
} else {
  aiReply = JSON.stringify(item);
}

return [{
  json: {
    workflowId: 'openai-gpt4o',
    message: aiReply.trim(),
    confidence: 0.9
  }
}];
